static CertificateInfo makeInfo(std::span<const uint8_t> input, unsigned flags)
{
    CertificateInfo::certificate_chain chain;
    chain.append(Vector<uint8_t> { input });
    return CertificateInfo(WTF::move(chain), flags);
}

int main()
{
    WTF::initializeMainThread();
    auto info = makeInfo(certificate, 7);
    auto copy = info.isolatedCopy();
    if (copy != info || copy.validationErrors() != 7 || CertificateInfo().summary())
        return 1;
    auto summary = copy.summary();
    if (!summary || summary->subject != "CN=fixture.clarke.test"_s
        || summary->validFrom.seconds() != 1704164645.0 || summary->validUntil.seconds() != 1896321906.0)
        return 2;
    if (summary->dnsNames.size() != 2 || summary->dnsNames[0] != "fixture.clarke.test"_s
        || summary->dnsNames[1] != "alt.clarke.test"_s
        || summary->ipAddresses.size() != 2 || summary->ipAddresses[0] != "192.0.2.17"_s
        || summary->ipAddresses[1] != "2001:DB8:0:0:0:0:0:42"_s)
        return 3;
    auto truncated = makeInfo(std::span { certificate }.first(sizeof(certificate) - 1), 0);
    Vector<uint8_t> extra { std::span { certificate } };
    extra.append(0);
    auto appended = makeInfo(extra.span(), 0);
    if (truncated.summary() || appended.summary())
        return 4;

    std::puts("XOS_WEBKIT_CERTIFICATE_OK subject validity dns ipv4 ipv6 invalid_der");
    return 0;
}
